//! Transport and lifecycle failure drills against a real relay.
//!
//! Delivery working on a healthy loopback says nothing about cancellation, a
//! relay dying mid-group, a publisher coming back, or bursts crossing a relay
//! cluster. Each drill here disrupts a live session over real QUIC and asserts
//! three things:
//!
//! 1. the fault actually activated, recorded as a value the test prints;
//! 2. the failure surfaced as a terminal result, never a clean finish or a hang;
//! 3. the resources it owned were released.
//!
//! Each drill runs in two lanes, generated by [`lanes!`] so a scenario cannot
//! drift between them: `loopback`, and `impaired`, where every client reaches
//! the relay through a seeded [`moq_shaper`] that delays, jitters, drops,
//! reorders, and rate-limits the path both ways (and, across a cluster, the
//! peer link between relays too). A drill that only passes on loopback is a
//! finding, not a flake. The impaired lane draws a fresh seed every run, a soak
//! rather than a gate, so it is ignored here and runs nightly.
//!
//! `no_publisher_never_delivers` is the negative control: the same harness with
//! nothing publishing must report failure, so a drill that passes because no
//! data ever moved cannot hide here.
//!
//! See `test/drill/README.md` for the recipe, the sensitivity proof that each
//! drill fails when its recovery behavior is removed, and the fuzz targets
//! covering the wire underneath.
#![cfg(all(feature = "quic", feature = "websocket"))]
#![expect(
	clippy::disallowed_methods,
	clippy::disallowed_types,
	reason = "tests read the host clock directly"
)]

use std::time::Duration;

use futures::FutureExt;

use moq_relay::{Config, Relay};
use moq_tokio::moq_net;

/// A millisecond track: the frames written here carry timestamps.
fn timed() -> moq_net::track::Info {
	moq_net::track::Info::default().with_timescale(moq_net::Timescale::MILLI)
}

/// Ceiling for anything a drill waits on. Every wait is bounded, so a broken
/// handoff fails as a timeout with a message instead of hanging the suite.
const TIMEOUT: Duration = Duration::from_secs(10);

/// How long a stalled reader sits on its hands, and how far the publisher runs
/// ahead of it. Long enough that the backlog is unambiguous, short enough to
/// stay a unit test.
const STALL: Duration = Duration::from_millis(300);
const STALL_GROUPS: usize = 8;

/// The track every drill publishes.
const TRACK: &str = "drill";

/// The impaired lane's treatment, the same both ways: a workable path, not a
/// hostile one, and the drills' own budgets (a 2s idle timeout, 10s waits) hold
/// under it unchanged. The loss is 5% because a drill only sends a few hundred
/// datagrams, and at 2% that is a drop or two, which barely exercises recovery.
/// Random loss only proves correctness, which is all a drill asserts; nothing
/// here judges quality, latency or throughput.
fn impairment() -> moq_shaper::Profile {
	moq_shaper::Profile {
		delay: Duration::from_millis(20),
		jitter: Duration::from_millis(5),
		loss: 0.05,
		reorder: 0.02,
		rate: Some(moq_shaper::Rate {
			bits_per_second: 10_000_000,
			// One datagram's worth, so a back-to-back flight is paced rather
			// than let through whole.
			burst: 1500,
			queue: Duration::from_millis(100),
		}),
	}
}

/// Which path a drill's clients take to the relay.
#[derive(Clone, Copy, Debug)]
enum Lane {
	Loopback,
	Impaired,
}

/// Run a drill in every [`Lane`], as a module of one test per lane.
macro_rules! lanes {
	($drill:ident) => {
		mod $drill {
			#[tokio::test]
			async fn loopback() {
				super::$drill(super::Lane::Loopback).await
			}

			#[tokio::test]
			#[ignore = "a fresh shaper seed per run is a nightly soak: just test drill impaired"]
			async fn impaired() {
				super::$drill(super::Lane::Impaired).await
			}
		}
	};
}

/// The path clients dial, and the shaper on it in the impaired lane.
///
/// The shaper runs on the test's runtime rather than the relay's, so killing
/// the relay leaves the path up, like a network outliving the server behind it.
struct Path {
	url: url::Url,
	shaper: Option<moq_shaper::Shaper>,
}

impl Path {
	async fn start(lane: Lane, relay: &RelayHost) -> Self {
		Self::shaped(lane, relay, impairment(), seed(lane)).await
	}

	/// [`Self::start`], treating the impaired lane to `profile` both ways with
	/// the shaper seeded by `seed`.
	async fn shaped(lane: Lane, relay: &RelayHost, profile: moq_shaper::Profile, seed: u64) -> Self {
		match lane {
			Lane::Loopback => Self {
				url: relay.url(),
				shaper: None,
			},
			Lane::Impaired => Self::through(relay, profile, seed).await,
		}
	}

	/// A shaper in front of `relay` in any lane, treating the path to `profile`
	/// both ways, seeded by `seed`.
	async fn through(relay: &RelayHost, profile: moq_shaper::Profile, seed: u64) -> Self {
		let shaper = moq_shaper::Shaper::bind(moq_shaper::Config {
			bind: "127.0.0.1:0".parse().unwrap(),
			target: relay.addr(),
			seed,
			up: profile.clone(),
			down: profile,
		})
		.await
		.expect("start the shaper");
		println!("shaper: seed {seed}, profile {:?}", shaper.config().up);

		Self {
			url: format!("https://{}/drill", shaper.addr()).parse().unwrap(),
			shaper: Some(shaper),
		}
	}

	/// Forward to `relay` from now on, so clients reach it at the address they
	/// already dial.
	fn retarget(&self, relay: &RelayHost) {
		self.shaper
			.as_ref()
			.expect("only a path through a shaper can move")
			.retarget(relay.addr())
			.expect("retarget the shaper");
	}

	/// Fail the drill unless the impairment it ran under actually acted.
	///
	/// A profile that silently did nothing would turn this lane into a second
	/// loopback run that passes for free.
	fn verify(mut self) {
		if let Some(shaper) = self.shaper.take() {
			let stats = shaper.verify().unwrap_or_else(|err| panic!("shaper: {err:#}"));
			println!("shaper: {stats}");
		}
	}

	/// Datagrams the shaper has dropped from a full rate-limit queue so far, both ways.
	fn overflowed(&self) -> u64 {
		self.shaper.as_ref().map_or(0, |shaper| {
			let stats = shaper.stats();
			stats.up.overflowed + stats.down.overflowed
		})
	}
}

/// A drill's base shaper seed, printed in the impaired lane. A fresh seed each
/// run explores more of the decision space; `MOQ_SHAPER_SEED` set to the
/// printed one replays a failure's decisions. A drill with several paths seeds
/// each one off it.
fn seed(lane: Lane) -> u64 {
	let seed = match std::env::var("MOQ_SHAPER_SEED") {
		Ok(seed) => seed.parse().expect("MOQ_SHAPER_SEED is not a u64"),
		Err(_) => rand::random(),
	};
	if let Lane::Impaired = lane {
		println!("impaired: MOQ_SHAPER_SEED={seed}");
	}
	seed
}

impl Drop for Path {
	fn drop(&mut self) {
		// A drill that failed before `verify` still reports what the path did,
		// including a shaper that stopped forwarding, which the drill itself
		// only sees as a client timing out.
		if let Some(shaper) = &self.shaper {
			match shaper.verify() {
				Ok(stats) => println!("shaper: {stats}"),
				Err(err) => println!("shaper: {err:#}"),
			}
		}
	}
}

/// A relay on its own runtime, so a drill can kill it the way a crash does.
///
/// Aborting the `run` task is not enough: the relay accept loop spawns a task per
/// connection, and those keep serving a relay whose accept loop is gone. Owning
/// the runtime means one shutdown takes the accept loop, every connection task,
/// and the UDP socket at once.
struct RelayHost {
	port: u16,
	/// `None` once killed, which is also what stops [`Drop`] from killing twice.
	runtime: Option<tokio::runtime::Runtime>,
}

impl RelayHost {
	/// Bind a relay running `config` and wait for it to be ready to accept.
	async fn start(config: Config) -> Self {
		// Process-global; every drill in this binary races to be first.
		let _ = rustls::crypto::aws_lc_rs::default_provider().install_default();

		let runtime = tokio::runtime::Builder::new_multi_thread()
			.worker_threads(2)
			.enable_all()
			.build()
			.expect("build relay runtime");

		let (ready, bound) = tokio::sync::oneshot::channel();
		runtime.spawn(async move {
			match Relay::load(config).await {
				Ok(relay) => {
					let _ = ready.send(Ok(relay.addr()));
					let _ = relay.run().await;
				}
				Err(err) => {
					let _ = ready.send(Err(format!("{err:#}")));
				}
			}
		});

		let addr = tokio::time::timeout(TIMEOUT, bound)
			.await
			.expect("relay startup timed out")
			.expect("relay task vanished during startup")
			.expect("relay failed to load");
		let port = addr.expect("relay did not bind UDP").port();

		Self {
			port,
			runtime: Some(runtime),
		}
	}

	/// Kill the relay: drop the runtime, taking every task and socket with it.
	///
	/// The shutdown blocks, so it runs on a blocking thread rather than in the
	/// test's own runtime. The timeout only bounds how long a stuck worker
	/// delays the test; the tasks are already gone when it expires.
	async fn kill(&mut self) {
		let runtime = self.runtime.take().expect("relay already killed");
		tokio::task::spawn_blocking(move || runtime.shutdown_timeout(Duration::from_secs(1)))
			.await
			.expect("relay shutdown panicked");
	}

	/// The relay's UDP address.
	fn addr(&self) -> std::net::SocketAddr {
		std::net::SocketAddr::from((std::net::Ipv4Addr::LOCALHOST, self.port))
	}

	/// The URL clients dial. `https` is WebTransport over QUIC.
	fn url(&self) -> url::Url {
		format!("https://{}/drill", self.addr())
			.parse()
			.expect("parse relay url")
	}
}

/// A public relay on an ephemeral loopback port with a generated certificate.
fn relay_config() -> Config {
	let mut config = Config::default();
	config.listen.bind = Some("127.0.0.1:0".parse().unwrap());
	config.listen.tls.generate = vec!["localhost".into()];
	config.auth.public = vec![moq_auth::Pattern::all()];
	config
}

impl Drop for RelayHost {
	fn drop(&mut self) {
		// A drill that ends (or panics) with the relay still up must not leave
		// its threads and socket behind for the next one to trip over.
		if let Some(runtime) = self.runtime.take() {
			runtime.shutdown_background();
		}
	}
}

/// A client that trusts the relay's generated certificate and speaks QUIC only.
///
/// The WebSocket fallback is off on purpose: these drills are about the QUIC
/// path, and a silent fallback would grade a different transport than the one
/// under test.
fn client(url: &url::Url) -> moq_tokio::Client {
	client_over(url, quic())
}

/// The drills' QUIC tuning for a client.
fn quic() -> moq_tokio::quic::Config {
	// A killed relay sends no CONNECTION_CLOSE, so the idle timeout is the only
	// thing that ever tells a client it is gone. The 30s default would put that
	// discovery past every budget here. The keep-alive is an eighth of it, so a
	// busy runner has to stall eight times over before a live session is mistaken
	// for a dead one.
	let mut quic = moq_tokio::quic::Config::default();
	quic.idle_timeout = Some((Duration::from_secs(2)).into());
	quic.keep_alive = Some((Duration::from_millis(250)).into());
	quic
}

/// [`client`], with `quic` as its transport tuning.
fn client_over(url: &url::Url, quic: moq_tokio::quic::Config) -> moq_tokio::Client {
	let mut config = dial();
	config.url = Some(url.clone());
	config.init(quic).expect("client init")
}

/// How a drill's clients, and a relay dialing a peer, connect: trusting the
/// generated certificate, over QUIC only, from an ephemeral loopback port.
fn dial() -> moq_tokio::connect::Config {
	let mut config = moq_tokio::connect::Config::default();
	config.bind = Some("127.0.0.1:0".parse().expect("parse client bind"));
	config.tls.insecure = Some(true);
	config.websocket.enabled = Some(false);

	// Fast enough to keep a relay bounce or a link flap inside the drill's
	// budget, paced enough that the loop is still a backoff.
	config.backoff.initial = Some((Duration::from_millis(50)).into());
	config.backoff.max = Some((Duration::from_millis(200)).into());
	config.backoff.timeout = Some((Duration::from_secs(5)).into());
	config
}

/// Append one finished group carrying `payload`.
fn write_group(track: &mut moq_net::track::Producer, payload: &[u8]) {
	let mut group = track.append_group().expect("append group");
	group
		.write_frame(moq_net::Timestamp::ZERO, payload)
		.expect("write frame");
	group.finish().expect("finish group");
}

/// Read the next group's first frame, failing the drill on a timeout, a clean
/// finish, or an empty group.
async fn read_group(reader: &mut Reader, what: &str) -> (u64, Vec<u8>) {
	let group = tokio::time::timeout(TIMEOUT, reader.groups.recv_group())
		.await
		.unwrap_or_else(|_| panic!("{what}: no group within {TIMEOUT:?}"))
		.unwrap_or_else(|err| panic!("{what}: track aborted: {err}"))
		.unwrap_or_else(|| panic!("{what}: track finished instead of delivering a group"));
	let sequence = group.sequence;

	let mut group = group;
	let frame = tokio::time::timeout(TIMEOUT, group.read_frame())
		.await
		.unwrap_or_else(|_| panic!("{what}: no frame within {TIMEOUT:?}"))
		.unwrap_or_else(|err| panic!("{what}: group aborted: {err}"))
		.unwrap_or_else(|| panic!("{what}: group finished with no frame"));

	(sequence, frame.payload.to_vec())
}

/// Read until `want` arrives, tolerating groups the disruption truncated.
///
/// A drill that resumes after an outage is asking whether new content flows, not
/// what happened to the groups caught in it, so a group whose frames went with
/// the old session is skipped here. A track-level failure is still fatal: that
/// says the subscription itself did not survive.
async fn read_until(reader: &mut Reader, want: &[u8], what: &str) {
	tokio::time::timeout(TIMEOUT, async {
		loop {
			let mut group = match reader.groups.recv_group().await {
				Ok(Some(group)) => group,
				Ok(None) => panic!("{what}: the track finished instead of resuming"),
				Err(err) => panic!("{what}: the track aborted: {err}"),
			};
			if let Ok(Some(frame)) = group.read_frame().await
				&& frame.payload == want
			{
				return;
			}
		}
	})
	.await
	.unwrap_or_else(|_| panic!("{what}: {} never arrived", String::from_utf8_lossy(want)));
}

/// Everything a drill holds on the subscribing side of one broadcast.
struct Reader {
	/// The broadcast the session feeds. Outlives the subscription so a drill can
	/// watch what a cancel or a session loss does to it.
	broadcast: moq_net::broadcast::Consumer,
	/// The local mirror of the publisher's track: `latest()` is what arrived,
	/// whatever the subscriber below has bothered to read.
	track: moq_net::track::Consumer,
	groups: moq_net::track::Subscriber,
}

/// Wait for `path` to be announced, then subscribe to [`TRACK`].
async fn subscribe(origin: &moq_net::origin::Consumer, path: &str) -> Reader {
	// Following parks until a route covers the path, where a request could find the
	// discovery synced before the announcement reaches this relay.
	let broadcast = tokio::time::timeout(TIMEOUT, origin.follow(path, None).unwrap().available())
		.await
		.expect("announcement timed out")
		.expect("origin closed before announcing");

	let track = broadcast.track(TRACK).expect("track");
	let groups = tokio::time::timeout(TIMEOUT, track.subscribe(None))
		.await
		.expect("subscribe timed out")
		.expect("subscribe rejected");

	Reader {
		broadcast,
		track,
		groups,
	}
}

/// Drill: stall a reader until a backlog builds, then cancel it.
///
/// The fault is a live subscription with unread groups stacked up behind it.
/// Cancelling there has to end cleanly on both counts: the handles that
/// subscription fed are released rather than left parked for a reader that will
/// never return, and the relay keeps serving everyone else.
///
/// What it deliberately does not assert is the publisher going idle. That
/// edge is the origin front's: it drops the source track when the last local
/// reader leaves, and is covered by moq-net's origin tests. This drill grades
/// the cancel itself: the stalled reader's handles release, and everyone else
/// keeps being served. The rejoin below is the half of that behavior worth
/// grading here.
async fn cancel_under_backpressure_releases_the_reader(lane: Lane) {
	let relay = RelayHost::start(relay_config()).await;
	let path = Path::start(lane, &relay).await;
	let url = path.url.clone();

	let publisher = moq_tokio::origin::spawn();
	let broadcast = publisher.create_broadcast("live").expect("create broadcast");
	broadcast.announce(Default::default()).expect("announce broadcast");
	let mut track = broadcast.create_track(TRACK, timed()).expect("create track");
	let publish_session = tokio::time::timeout(
		TIMEOUT,
		client(&url)
			.with_publisher(&publisher)
			.with_reconnect(false)
			.connect(url.clone())
			.established(),
	)
	.await
	.expect("publisher connect timed out")
	.expect("publisher connect failed");

	let subscriber = moq_tokio::origin::spawn();
	let subscribed = subscriber.consume();
	let subscribe_session = tokio::time::timeout(
		TIMEOUT,
		client(&url)
			.with_subscriber(subscriber)
			.with_reconnect(false)
			.connect(url.clone())
			.established(),
	)
	.await
	.expect("subscriber connect timed out")
	.expect("subscriber connect failed");

	write_group(&mut track, b"first");
	let mut reader = subscribe(&subscribed, "live").await;
	let (first, payload) = read_group(&mut reader, "before the stall").await;
	assert_eq!(payload, b"first", "delivery is broken before the drill even starts");

	// The stall: the reader stops asking while the publisher runs ahead of it.
	for i in 0..STALL_GROUPS {
		write_group(&mut track, format!("stalled {i}").as_bytes());
		tokio::time::sleep(STALL / STALL_GROUPS as u32).await;
	}

	// Fault activation: the groups reached the subscriber and stacked up behind a
	// reader that never asked for them, so the cancel below lands on a live
	// subscription with a real backlog rather than on an idle one. Nothing blocks
	// a moq publisher (`write_frame` is synchronous, and a reader that falls too
	// far behind is shed rather than waited for), so an unread backlog is what
	// backpressure looks like from here.
	let mut behind = None;
	let backlog = tokio::time::timeout(TIMEOUT, async {
		while let Some(largest) = reader.track.largest().await {
			behind = Some(largest.group - first);
			if largest.group >= first + STALL_GROUPS as u64 {
				return largest.group - first;
			}
		}
		panic!("the stalled reader ended before its backlog queued");
	})
	.await
	.unwrap_or_else(|_| {
		panic!(
			"the stalled reader is only {behind:?} groups behind: nothing was queued, so there is no backlog to cancel under"
		)
	});
	println!("fault activated: cancelling with {backlog} unread groups queued");

	// Nothing has been released yet, so the release below cannot be reporting a
	// state that was already true.
	assert!(
		!reader.broadcast.is_closed(),
		"the subscriber's broadcast closed while it was still reading"
	);

	// The cancel, with the backlog outstanding.
	let cancelled = reader.broadcast.clone();
	drop(reader);
	drop(subscribe_session);

	// Resource release: everything that session was feeding is closed, rather
	// than left parked on a subscription nobody will ever serve again.
	tokio::time::timeout(TIMEOUT, cancelled.closed())
		.await
		.expect("the cancelled subscriber's broadcast never closed");
	println!("resource released: the cancelled broadcast closed");

	// ...and the relay survived it: a fresh subscriber still gets served, off the
	// upstream subscription the cancel left in place.
	let rejoin = moq_tokio::origin::spawn();
	let rejoined = rejoin.consume();
	let rejoin_session = tokio::time::timeout(
		TIMEOUT,
		client(&url)
			.with_subscriber(rejoin)
			.with_reconnect(false)
			.connect(url.clone())
			.established(),
	)
	.await
	.expect("rejoin connect timed out")
	.expect("rejoin connect failed");
	let mut rejoined_reader = subscribe(&rejoined, "live").await;
	write_group(&mut track, b"after cancel");
	read_until(&mut rejoined_reader, b"after cancel", "after the cancel").await;

	drop(rejoined_reader);
	drop(rejoin_session);
	drop(publish_session);
	path.verify();
}

lanes!(cancel_under_backpressure_releases_the_reader);

/// Drill: kill the relay mid-group, then bring it back.
///
/// Two things have to hold. An interrupted track must abort, because a clean
/// finish means "the publisher is done" and silently truncating a live stream
/// into one is the worst possible failure mode. And the reconnect loop has to
/// restore service: the dead session's broadcast closes with it, and a fresh
/// subscribe through the same origin resumes once the relay returns.
///
/// Clients dial a shaper in both lanes, unimpaired on loopback, so the relay
/// can come back on a fresh port behind the address they already dial. The
/// dead relay's port is free for any process's ephemeral bind to take, so a
/// restart that needed it back would fail whenever one did.
async fn relay_killed_mid_group_aborts_then_resumes(lane: Lane) {
	let mut relay = RelayHost::start(relay_config()).await;
	let profile = match lane {
		Lane::Loopback => Default::default(),
		Lane::Impaired => impairment(),
	};
	let path = Path::through(&relay, profile, seed(lane)).await;
	let url = path.url.clone();

	let publisher = moq_tokio::origin::spawn();
	let broadcast = publisher.create_broadcast("live").expect("create broadcast");
	broadcast.announce(Default::default()).expect("announce broadcast");
	let mut track = broadcast.create_track(TRACK, timed()).expect("create track");
	let mut publish_loop = client(&url).publish(publisher.consume()).expect("no connect url");

	let subscriber = moq_tokio::origin::spawn();
	let subscribed = subscriber.consume();
	let mut subscribe_loop = client(&url).consume(subscriber).expect("no connect url");

	write_group(&mut track, b"before");
	let mut reader = subscribe(&subscribed, "live").await;
	let (_, payload) = read_group(&mut reader, "before the kill").await;
	assert_eq!(payload, b"before", "delivery is broken before the drill even starts");

	// A group that is open, delivered as far as its first frame, and waited on for
	// a second: the kill lands mid-group rather than in the quiet between them.
	// Nothing more is written, so what the reader is waiting for cannot arrive
	// ahead of the kill and turn this into a race.
	let mut open = track.append_group().expect("append group");
	open.write_frame(moq_net::Timestamp::ZERO, b"read".as_ref())
		.expect("write frame");
	let mut open_reader = tokio::time::timeout(TIMEOUT, reader.groups.recv_group())
		.await
		.expect("open group timed out")
		.expect("track aborted")
		.expect("track finished");
	tokio::time::timeout(TIMEOUT, open_reader.read_frame())
		.await
		.expect("open frame timed out")
		.expect("open group aborted")
		.expect("open group finished");

	// Start the replacement while the original still holds its port, so the two
	// can never share one. Clients keep dialing the dead relay until the retarget.
	let replacement = RelayHost::start(relay_config()).await;
	relay.kill().await;

	// Terminal result: the unread half of the open group fails. `Ok(None)` here
	// would be the relay's death passing for the publisher finishing.
	let err = tokio::time::timeout(TIMEOUT, open_reader.read_frame())
		.await
		.expect("the interrupted group never resolved")
		.expect_err("the interrupted group reported a clean finish");
	println!("fault activated: interrupted group aborted with {err}");

	// Fault activation: both loops noticed they lost the relay.
	expect_status(&mut subscribe_loop, moq_tokio::Status::Disconnected, "subscriber").await;
	expect_status(&mut publish_loop, moq_tokio::Status::Disconnected, "publisher").await;

	let relay = replacement;
	path.retarget(&relay);

	expect_status(&mut subscribe_loop, moq_tokio::Status::Connected, "subscriber").await;
	expect_status(&mut publish_loop, moq_tokio::Status::Connected, "publisher").await;

	// The outage is observed, not hidden: the broadcast the dead session fed closed
	// with it, so the old subscription ends rather than reading from a stale route.
	let err = match tokio::time::timeout(TIMEOUT, reader.groups.recv_group())
		.await
		.expect("the interrupted subscription never resolved")
	{
		Err(err) => err,
		Ok(_) => panic!("the interrupted subscription kept going instead of aborting"),
	};
	println!("fault activated: interrupted subscription aborted with {err}");
	drop(reader);

	// Resumed delivery through the same subscriber origin: the reconnected
	// publisher re-announced, and a fresh subscribe rides the new session.
	open.finish().expect("finish the interrupted group");
	write_group(&mut track, b"after");
	let mut reader = subscribe(&subscribed, "live").await;
	read_until(&mut reader, b"after", "after the restart").await;

	drop(reader);
	drop(subscribe_loop);
	drop(publish_loop);
	drop(relay);
	path.verify();
}

lanes!(relay_killed_mid_group_aborts_then_resumes);

/// Wait for a reconnect loop to report `want`, failing with what it said instead.
async fn expect_status(reconnect: &mut moq_tokio::Connection, want: moq_tokio::Status, who: &str) {
	loop {
		let status = tokio::time::timeout(TIMEOUT, reconnect.status())
			.await
			.unwrap_or_else(|_| panic!("{who}: no status change within {TIMEOUT:?}, wanted {want:?}"))
			.unwrap_or_else(|err| panic!("{who}: reconnect loop gave up: {err}"));
		if status == want {
			return;
		}
	}
}

/// Drill: interrupt a publisher, then republish the same name.
///
/// A crashed publisher must withdraw its broadcast rather than leave a name
/// announced that nothing serves, and the replacement has to be new content: a
/// subscriber that re-consumes the same name after a republish gets what the
/// new publisher is sending, never the previous one's cache.
async fn interrupted_publisher_republishes_new_content(lane: Lane) {
	let relay = RelayHost::start(relay_config()).await;
	let path = Path::start(lane, &relay).await;
	let url = path.url.clone();

	let subscriber = moq_tokio::origin::spawn();
	let subscribed = subscriber.consume();
	let subscribe_session = tokio::time::timeout(
		TIMEOUT,
		client(&url)
			.with_subscriber(subscriber)
			.with_reconnect(false)
			.connect(url.clone())
			.established(),
	)
	.await
	.expect("subscriber connect timed out")
	.expect("subscriber connect failed");
	let mut announced = subscribed.announced();

	let first = moq_tokio::origin::spawn();
	let broadcast = first.create_broadcast("live").expect("create broadcast");
	broadcast.announce(Default::default()).expect("announce broadcast");
	let mut track = broadcast.create_track(TRACK, timed()).expect("create track");
	let first_session = tokio::time::timeout(
		TIMEOUT,
		client(&url)
			.with_publisher(&first)
			.with_reconnect(false)
			.connect(url.clone())
			.established(),
	)
	.await
	.expect("publisher connect timed out")
	.expect("publisher connect failed");

	write_group(&mut track, b"original");
	expect_announce(&mut announced, "live", true, "the first publisher").await;
	let mut reader = subscribe(&subscribed, "live").await;
	let (_, payload) = read_group(&mut reader, "before the interrupt").await;
	assert_eq!(payload, b"original", "delivery is broken before the drill even starts");

	// Dropping the connection cancels its task asynchronously. Keep the broadcast
	// alive until the relay withdraws it, so a clean unannounce cannot race the
	// session loss and satisfy the assertion without testing crash recovery.
	drop(first_session);
	drop(reader);

	// Terminal result: the name stops being announced. Nothing told the relay
	// the broadcast ended, so this is the proof that losing the publisher's
	// session withdraws what it announced rather than parking subscribers on it.
	expect_announce(&mut announced, "live", false, "the interrupted publisher").await;
	println!("fault activated: the interrupted publisher's broadcast was withdrawn");
	drop(track);
	drop(broadcast);
	drop(first);

	// Restore: the same name, a new publisher, different content.
	let second = moq_tokio::origin::spawn();
	let broadcast = second.create_broadcast("live").expect("re-create broadcast");
	broadcast.announce(Default::default()).expect("announce broadcast");
	let mut track = broadcast.create_track(TRACK, timed()).expect("re-create track");
	let second_session = tokio::time::timeout(
		TIMEOUT,
		client(&url)
			.with_publisher(&second)
			.with_reconnect(false)
			.connect(url.clone())
			.established(),
	)
	.await
	.expect("republisher connect timed out")
	.expect("republisher connect failed");

	write_group(&mut track, b"replacement");
	expect_announce(&mut announced, "live", true, "the republisher").await;

	let mut reader = subscribe(&subscribed, "live").await;
	let (_, payload) = read_group(&mut reader, "after the republish").await;
	assert_eq!(
		payload, b"replacement",
		"the republished name served the dead publisher's content"
	);

	drop(reader);
	drop(track);
	drop(broadcast);
	drop(second_session);
	drop(subscribe_session);
	path.verify();
}

lanes!(interrupted_publisher_republishes_new_content);

/// Wait for `path` to be announced (`want`) or unannounced (`!want`).
async fn expect_announce(announced: &mut moq_net::announce::Consumer, path: &str, want: bool, who: &str) {
	loop {
		let (update, active) = tokio::time::timeout(TIMEOUT, next_update(announced))
			.await
			.unwrap_or_else(|_| panic!("{who}: no announcement change within {TIMEOUT:?}"))
			.unwrap_or_else(|| panic!("{who}: the announcement stream closed"));
		if update.prefix.as_str() == path && active == want {
			return;
		}
	}
}

/// How many bursts the cross-relay drill sends, and how many one-frame groups
/// each holds: a control channel firing messages back to back.
const BURSTS: u64 = 4;
const BURST_GROUPS: u64 = 30;

/// Each cross-relay group's payload size, about what a small control message is.
const PAYLOAD: usize = 256;

/// How long a cross-relay group may take, from being written, to arrive. Several
/// times the slowest group seen on the impaired path, and a third of the 30s
/// stalls of #4349.
const SETTLE: Duration = Duration::from_secs(10);

/// The cross-relay drill's link: a bottleneck a burst overruns, so its tail
/// waits in the queue or is dropped from it. Random loss and reordering cannot
/// establish that congestion acted, so only overflow supplies loss here. It is
/// slower than [`credit`]'s stream window lets a sender go. The first burst
/// is collected at ingress after setup, so scheduling cannot drain the bucket
/// between its datagrams; its bytes exceed the burst and 50ms queue allowance
/// before they are accounted at one instant.
fn bursty() -> moq_shaper::Profile {
	moq_shaper::Profile {
		delay: Duration::from_millis(20),
		rate: Some(moq_shaper::Rate {
			bits_per_second: 100_000,
			burst: 1500,
			queue: Duration::from_millis(50),
		}),
		..Default::default()
	}
}

/// QUIC credit tighter than a burst on the impaired lane: fewer concurrent
/// streams than a burst has groups (each group is a stream, each FETCH another),
/// and stream windows of a few groups, so senders wait on MAX_STREAMS and
/// MAX_STREAM_DATA mid-burst while the path is congested. The connection window
/// keeps its default, since it has to fit the largest message a session assembles.
fn credit(lane: Lane, mut quic: moq_tokio::quic::Config) -> moq_tokio::quic::Config {
	if let Lane::Impaired = lane {
		quic.max_streams = Some(16);
		// The one-shot ingress burst must fit inside transport credit before
		// anything is released. Keep two bucket allowances, rounded to groups.
		quic.stream_receive_window = Some(ingress_bytes());
	}
	quic
}

/// Enough bytes to cross the ingress bucket without needing an acknowledgment.
fn ingress_bytes() -> u64 {
	let rate = bursty().rate.expect("bursty rate");
	let queued = (rate.bits_per_second as u128 * rate.queue.as_nanos() / 8 / 1_000_000_000) as u64;
	(rate.burst + queued).next_multiple_of(PAYLOAD as u64) * 2
}

/// How a cross-relay group reached the subscriber, or why it never did.
#[derive(Debug)]
enum Outcome {
	/// The live subscription delivered it.
	Live,
	/// A FETCH recovered it after the subscription skipped or lost it.
	Fetched,
	/// The FETCH failed, with this error.
	Failed(String),
	/// The FETCH got no answer within [`SETTLE`].
	Unanswered,
	/// The live subscription opened it but its frame never came within [`SETTLE`].
	Stalled,
}

/// One thing the cross-relay subscriber waits on.
enum Step {
	/// The live subscription's next group.
	Group(Box<moq_net::Result<Option<moq_net::group::Consumer>>>),
	/// A group read or FETCH, made through the numbered subscription, finished.
	Settled(u64, Outcome, u64),
	/// A route to this path started (`true`) or ended (`false`).
	Route(String, bool),
}

/// Read the one frame of group `sequence`, checking it is the payload written there.
async fn read_payload(mut group: moq_net::group::Consumer, sequence: u64) -> Result<(), String> {
	match group.read_frame().await {
		Ok(Some(frame)) if frame.payload == payload(sequence) => Ok(()),
		Ok(Some(_)) => panic!("group {sequence} carried another group's payload"),
		Ok(None) => Err("finished with no frame".to_string()),
		Err(err) => Err(err.to_string()),
	}
}

/// The group number, padded so the first burst's newest group can fill ingress.
fn payload(sequence: u64) -> Vec<u8> {
	// A latest-only subscription can skip every earlier group in a burst.
	// Its newest frame alone must cross the gate before it needs an ACK.
	let width = if sequence == BURST_GROUPS - 1 {
		ingress_bytes() as usize
	} else {
		PAYLOAD
	};
	format!("{sequence:>width$}").into_bytes()
}

/// Drill: bursts of one-frame groups cross a two-relay cluster.
///
/// A publisher on an origin relay sends bursts of tens of single-frame groups.
/// A subscriber on an edge relay, which reaches the origin as a cluster peer,
/// reads them with the default subscription (only the newest group) and FETCHes
/// every group below it that the subscription skipped or reset, the way a
/// control channel that must apply every message recovers. In the impaired lane
/// every hop (publisher, peer link, subscriber) runs through a shaper that a
/// burst overruns, and every endpoint grants less QUIC credit than a burst needs.
///
/// Nothing is evicted and no link goes down, so every group has to arrive within
/// [`SETTLE`] of being written; one that does not fails the drill by name, with
/// how it was lost: a FETCH that failed, a FETCH nobody answered, or a live group
/// that stalled. The newest group has to come over the live subscription, since
/// nothing newer can replace it.
async fn bursts_cross_a_cluster(lane: Lane) {
	cross_cluster(lane, PeerLink::Steady).await
}

lanes!(bursts_cross_a_cluster);

/// Drill: [`bursts_cross_a_cluster`], with the peer link flapping mid-recovery.
///
/// The link between the relays is cut as the second burst is written, once the
/// first has started arriving, so the first burst's gap FETCHes are in flight and
/// the second is stranded at the origin. It stays down until the subscriber sees the edge withdraw the route, then
/// comes back and the edge redials. That is a route flap: the regression for the
/// groups 0.15.6 dropped across one (#4349). The subscriber re-subscribes once
/// the route returns, and every read or FETCH the flap failed is claimed again
/// through it, the way an app recovering a control channel would.
///
/// The grading stays as strict: the publisher keeps every group, so each still
/// arrives within [`SETTLE`] of being written, or of the route coming back when it
/// arrives after that, or fails the drill by name. Only a failure the flap caused
/// is retried; a read or FETCH on the dead route that outlasts the relays' idle
/// timeout, or a withdrawal while the link was up, still fails it.
async fn bursts_cross_a_flapping_peer(lane: Lane) {
	cross_cluster(lane, PeerLink::Flapping).await
}

lanes!(bursts_cross_a_flapping_peer);

/// Drill: [`bursts_cross_a_cluster`], with the relays peering over moq-transport.
///
/// The gap FETCHes cross the peer link as IETF FETCHes, so a group the origin
/// still holds has to be served through that path too, not refused.
async fn bursts_cross_a_transport_peer(lane: Lane) {
	cross_cluster(lane, PeerLink::Transport).await
}

lanes!(bursts_cross_a_transport_peer);

/// How the cross-relay drill's peer link behaves.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PeerLink {
	/// Up throughout, on the version the relays negotiate by default.
	Steady,
	/// Cut mid-recovery, then restored.
	Flapping,
	/// Up throughout, on moq-transport.
	Transport,
}

/// The burst a flapping peer link is cut just before: after one that started
/// crossing the link, and before the bursts that prove the restored route carries on.
const FLAP_BURST: u64 = 1;

/// Where a flapping peer link stands.
enum Flap {
	/// Not cut, or never will be.
	Up,
	/// Cut at `at`, with the route over it still announced.
	Cut {
		outage: moq_shaper::Outage,
		at: tokio::time::Instant,
	},
	/// The edge withdrew the route after the link was down for `cut`. The link
	/// is back and the edge redials.
	Withdrawn { cut: Duration },
	/// The route came back and the subscriber re-subscribed through it.
	Restored { cut: Duration },
}

impl Flap {
	/// Whether the route is down or going, so a read or FETCH through it may fail.
	fn flapping(&self) -> bool {
		matches!(self, Flap::Cut { .. } | Flap::Withdrawn { .. })
	}
}

async fn cross_cluster(lane: Lane, link: PeerLink) {
	// On the impaired path the relays keep the default idle timeout. The drills'
	// 2s one would also bound each relay's side of an impaired handshake, which
	// can sit silent that long between the client's backed-off retransmits.
	// Loopback has no such silence, so its relays take the clients' tuning. A cut
	// peer link idles out only after `relay_idle`, which the flap's waits allow for.
	let relay_quic = || match lane {
		Lane::Loopback => quic(),
		Lane::Impaired => credit(lane, relay_config().quic),
	};
	let mut config = relay_config();
	config.quic = relay_quic();
	let relay_idle = config.quic.resolve().idle_timeout;
	let origin = RelayHost::start(config).await;
	let seed = seed(lane);
	let peer = match (link, lane) {
		(PeerLink::Steady | PeerLink::Transport, _) => Path::shaped(lane, &origin, bursty(), seed).await,
		// Cutting the link takes a shaper on it, so loopback gets one that forwards untouched.
		(PeerLink::Flapping, Lane::Loopback) => Path::through(&origin, Default::default(), seed).await,
		(PeerLink::Flapping, Lane::Impaired) => Path::through(&origin, bursty(), seed).await,
	};

	// The edge relay dials the origin as a cluster peer, through its own path.
	let mut peer_url = peer.url.clone();
	peer_url.set_path("/");
	let mut config = relay_config();
	config.quic = relay_quic();
	config.connect = dial();
	// Retry forever: a give-up after a slow impaired handshake would look exactly
	// like the never-redialed regression, and a stall still fails the drill.
	config.connect.backoff.timeout = Some((Duration::ZERO).into());
	if link == PeerLink::Transport {
		config.connect.version = vec!["moq-transport-22".parse().expect("parse version")];
	}
	config.cluster.connect = vec![moq_relay::cluster::Peer::new(peer_url.to_string())];
	let edge = RelayHost::start(config).await;

	let publish_path = Path::shaped(lane, &origin, bursty(), seed.wrapping_add(1)).await;
	let subscribe_path = Path::shaped(lane, &edge, bursty(), seed.wrapping_add(2)).await;

	let publisher = moq_tokio::origin::spawn();
	let broadcast = publisher.create_broadcast("live").expect("create broadcast");
	broadcast.announce(Default::default()).expect("announce broadcast");
	let mut track = broadcast.create_track(TRACK, timed()).expect("create track");
	let url = publish_path.url.clone();
	let publish_session = tokio::time::timeout(
		TIMEOUT,
		client_over(&url, credit(lane, quic()))
			.with_publisher(&publisher)
			.with_reconnect(false)
			.connect(url)
			.established(),
	)
	.await
	.expect("publisher connect timed out")
	.expect("publisher connect failed");

	let subscriber = moq_tokio::origin::spawn();
	let subscribed = subscriber.consume();
	let mut announced = subscribed.announced();
	let url = subscribe_path.url.clone();
	let subscribe_session = tokio::time::timeout(
		TIMEOUT,
		client_over(&url, credit(lane, quic()))
			.with_subscriber(subscriber)
			.with_reconnect(false)
			.connect(url)
			.established(),
	)
	.await
	.expect("subscriber connect timed out")
	.expect("subscriber connect failed");

	// Subscribed before the first burst, as an app watching a control channel is.
	let mut reader = subscribe(&subscribed, "live").await;
	// The subscriber's subscription can start before the origin's reaches the
	// publisher, which takes extra round trips over a moq-transport peer. The
	// ingress burst holds every publisher datagram, including the replies and
	// credit the origin needs before it subscribes, so arming it any earlier
	// starves the publisher's session until it idles out.
	tokio::time::timeout(TIMEOUT, async {
		while track.subscription().is_none() {
			track.subscription_changed().await.expect("track aborted");
		}
	})
	.await
	.expect("the origin never subscribed to the publisher");

	// What connecting and subscribing overflowed, so only the bursts are graded.
	let paths = [&peer, &publish_path, &subscribe_path];
	let setup_overflowed: u64 = paths.iter().map(|path| path.overflowed()).sum();
	let ingress = match lane {
		Lane::Impaired => Some(
			publish_path
				.shaper
				.as_ref()
				.expect("impaired path")
				.burst(moq_shaper::ingress::Direction::Up)
				.expect("arm an ingress burst"),
		),
		Lane::Loopback => None,
	};

	let total = BURSTS * BURST_GROUPS;
	let mut written = Vec::new();
	let mut flap = Flap::Up;
	// Write the next burst, cutting a flapping link just before the flap burst.
	// A burst is written without yielding, so a cut partway through it would
	// still land before any of it left the publisher.
	let burst = |track: &mut moq_net::track::Producer, written: &mut Vec<tokio::time::Instant>, flap: &mut Flap| {
		if link == PeerLink::Flapping && written.len() as u64 == FLAP_BURST * BURST_GROUPS {
			let outage = peer.shaper.as_ref().expect("a flapping link has a shaper").cut();
			*flap = Flap::Cut {
				outage,
				at: tokio::time::Instant::now(),
			};
		}
		for _ in 0..BURST_GROUPS {
			let sequence = written.len() as u64;
			write_group(track, &payload(sequence));
			written.push(tokio::time::Instant::now());
		}
	};
	burst(&mut track, &mut written, &mut flap);

	// Each group is claimed once, by the subscription or by a FETCH, and settles
	// in `pending`. A live group that fails is a gap like any other, so it is
	// FETCHed in turn. Each read and FETCH is tagged with the subscription it went
	// through, counted from zero, so one the flap took down can be told apart.
	let mut claimed = std::collections::BTreeSet::new();
	let mut live = std::collections::BTreeSet::new();
	let mut outcomes = std::collections::BTreeMap::new();
	let mut pending = tokio::task::JoinSet::new();
	let mut resets = Vec::new();
	let mut flapped = Vec::new();
	let mut slowest = (Duration::ZERO, 0);
	let mut generation = 0u64;
	let mut subscription_up = true;
	// When the route was restored after a flap. A group that settles after it is
	// timed from it, since the publisher could not reach the subscriber before.
	let mut restored_at = None;
	// How long one read or FETCH may take. A flap leaves those on the dead route
	// waiting until the edge's peer session idles out, so they get that much more;
	// one that outlasts even that hung on the dead route and still fails the drill.
	let wait = match link {
		PeerLink::Steady | PeerLink::Transport => SETTLE,
		PeerLink::Flapping => SETTLE + relay_idle,
	};
	let fetch =
		|pending: &mut tokio::task::JoinSet<_>, track: &moq_net::track::Consumer, sequence: u64, generation: u64| {
			let fetching = track.fetch_group(sequence, None);
			pending.spawn(async move {
				let fetched = tokio::time::timeout(wait, async {
					let group = fetching.await.map_err(|err| err.to_string())?;
					read_payload(group, sequence).await
				});
				let outcome = match fetched.await {
					Ok(Ok(())) => Outcome::Fetched,
					Ok(Err(err)) => Outcome::Failed(err),
					Err(_) => Outcome::Unanswered,
				};
				(sequence, outcome, generation)
			});
		};

	// A margin past each settle task's own timeout, so a group that times out is
	// reported by name rather than as a generic stall.
	let step_timeout = wait + Duration::from_secs(1);
	while (outcomes.len() as u64) < total {
		let step = tokio::time::timeout(step_timeout, async {
			tokio::select! {
				group = reader.groups.recv_group(), if subscription_up => Step::Group(Box::new(group)),
				Some(settled) = pending.join_next() => {
					let (sequence, outcome, generation) = settled.expect("settle task panicked");
					Step::Settled(sequence, outcome, generation)
				}
				Some((update, active)) = next_update(&mut announced) => Step::Route(update.prefix.to_string(), active),
			}
		})
		.await
		.unwrap_or_else(|_| {
			let missing: Vec<u64> = (0..total).filter(|sequence| !outcomes.contains_key(sequence)).collect();
			let link = match flap {
				Flap::Cut { .. } => " with the peer link cut",
				Flap::Withdrawn { .. } => " with the route withdrawn",
				Flap::Up | Flap::Restored { .. } => "",
			};
			panic!(
				"stalled{link}: nothing arrived within {step_timeout:?}, {} of {total} groups missing: {missing:?}",
				missing.len()
			)
		});

		match step {
			// The flap took this read or FETCH down with the route: claim the group
			// again through the restored one, now if it is back, or as a gap once it is.
			Step::Settled(sequence, Outcome::Failed(err), tagged) if tagged < generation || flap.flapping() => {
				live.remove(&sequence);
				flapped.push((sequence, err));
				match flap.flapping() {
					true => {
						claimed.remove(&sequence);
					}
					false => fetch(&mut pending, &reader.track, sequence, generation),
				}
			}
			Step::Settled(sequence, Outcome::Failed(err), _) if live.remove(&sequence) => {
				resets.push((sequence, err));
				fetch(&mut pending, &reader.track, sequence, generation);
			}
			Step::Settled(sequence, outcome, _) => {
				live.remove(&sequence);
				let since = written[sequence as usize].max(restored_at.unwrap_or(written[sequence as usize]));
				let late = since.elapsed();
				slowest = slowest.max((late, sequence));
				outcomes.insert(sequence, outcome);
			}
			Step::Route(path, active) => {
				assert_eq!(path, "live", "announced a broadcast nobody published");
				flap = match (active, flap) {
					// The edge noticed the cut and withdrew the route: restore the
					// link, so the edge's redial gets through.
					(false, Flap::Cut { outage, at }) => {
						drop(outage);
						Flap::Withdrawn { cut: at.elapsed() }
					}
					(false, _) => panic!("the route was withdrawn while the peer link was up"),
					(true, Flap::Withdrawn { cut }) => {
						restored_at = Some(tokio::time::Instant::now());
						reader = subscribe(&subscribed, "live").await;
						generation += 1;
						subscription_up = true;
						Flap::Restored { cut }
					}
					// The first announcement, or an update to a standing route.
					(true, flap) => flap,
				};
			}
			Step::Group(group) => {
				let group = match *group {
					Ok(Some(group)) => group,
					// The route went, and the subscription with it, until it returns.
					Err(_) if flap.flapping() => {
						subscription_up = false;
						continue;
					}
					Err(err) => panic!("the subscription aborted: {err}"),
					Ok(None) => panic!("the subscription finished"),
				};
				let sequence = group.sequence;

				// Every unclaimed group below this one is a gap the subscription
				// skipped: FETCH it now rather than wait.
				for gap in 0..sequence {
					if claimed.insert(gap) {
						fetch(&mut pending, &reader.track, gap, generation);
					}
				}
				if claimed.insert(sequence) {
					live.insert(sequence);
					pending.spawn(async move {
						let outcome = match tokio::time::timeout(wait, read_payload(group, sequence)).await {
							Ok(Ok(())) => Outcome::Live,
							Ok(Err(err)) => Outcome::Failed(err),
							Err(_) => Outcome::Stalled,
						};
						(sequence, outcome, generation)
					});
				}

				// The next burst leaves once this one starts arriving, so recovery
				// overlaps fresh data the way a busy control channel's does.
				if sequence + BURST_GROUPS >= written.len() as u64 && (written.len() as u64) < total {
					burst(&mut track, &mut written, &mut flap);
				}
			}
		}
	}

	// Fault activation: the subscription skipped or reset groups, so the FETCH
	// recovery below had something to recover, and in the impaired lane the
	// bursts overflowed a bottleneck.
	let gaps = outcomes
		.values()
		.filter(|outcome| !matches!(outcome, Outcome::Live))
		.count();
	if let Some(ingress) = ingress {
		ingress
			.completed()
			.now_or_never()
			.expect("ingress burst never completed")
			.expect("ingress burst cancelled");
	}
	let overflowed = paths.iter().map(|path| path.overflowed()).sum::<u64>() - setup_overflowed;
	println!(
		"fault activated: {gaps} of {total} groups missed the live subscription (reset: {resets:?}), {overflowed} datagrams overflowed a bottleneck during the bursts, slowest group {} after {:?}",
		slowest.1, slowest.0
	);
	assert!(gaps > 0, "every group came live, so no FETCH recovery was exercised");
	if let Lane::Impaired = lane {
		assert!(overflowed > 0, "no burst overran a bottleneck, so none was exercised");
	}
	match (link, flap) {
		(PeerLink::Steady | PeerLink::Transport, Flap::Up) => {}
		(PeerLink::Flapping, Flap::Restored { cut }) => println!(
			"fault activated: the peer link was down {cut:?} before the edge withdrew the route, which came back; the flap failed {} reads and FETCHes, each claimed again: {flapped:?}",
			flapped.len()
		),
		(PeerLink::Flapping, Flap::Up) => panic!("the peer link was never cut"),
		(PeerLink::Flapping, _) => panic!("the route never came back after the peer link flapped"),
		(PeerLink::Steady | PeerLink::Transport, _) => unreachable!("a steady link is never cut"),
	}

	let lost: Vec<_> = outcomes
		.iter()
		.filter(|(_, outcome)| !matches!(outcome, Outcome::Live | Outcome::Fetched))
		.collect();
	assert!(lost.is_empty(), "groups lost: {lost:?}");
	assert!(
		slowest.0 <= SETTLE,
		"group {} took {:?} to arrive, past {SETTLE:?}",
		slowest.1,
		slowest.0
	);
	assert!(
		matches!(outcomes.get(&(total - 1)), Some(Outcome::Live)),
		"the newest group came by {:?}, not the live subscription",
		outcomes.get(&(total - 1))
	);

	drop(reader);
	drop(subscribe_session);
	drop(publish_session);
	drop(edge);
	drop(origin);
	peer.verify();
	publish_path.verify();
	subscribe_path.verify();
}

/// Negative control: with nothing publishing, the drills' delivery assertions
/// have to fail.
///
/// Every drill above proves something by reading a frame. This one runs the same
/// harness with no publisher and requires that no announcement and no broadcast
/// ever arrive, so "the frame showed up" cannot be a harness artifact.
async fn no_publisher_never_delivers(lane: Lane) {
	let relay = RelayHost::start(relay_config()).await;
	let path = Path::start(lane, &relay).await;
	let url = path.url.clone();

	let subscriber = moq_tokio::origin::spawn();
	let subscribed = subscriber.consume();
	let session = tokio::time::timeout(
		TIMEOUT,
		client(&url)
			.with_subscriber(subscriber)
			.with_reconnect(false)
			.connect(url.clone())
			.established(),
	)
	.await
	.expect("subscriber connect timed out")
	.expect("subscriber connect failed");

	// Short on purpose: this is the one wait that must expire, so it is the one
	// wait that decides how long the suite spends proving a negative. Still
	// many round trips of either path.
	let quiet = match lane {
		Lane::Loopback => Duration::from_millis(300),
		Lane::Impaired => Duration::from_secs(2),
	};

	let mut announced = subscribed.announced();
	let mut following = subscribed.follow("live", None).unwrap();
	let (update, resolved) = tokio::join!(
		tokio::time::timeout(quiet, next_update(&mut announced)),
		tokio::time::timeout(quiet, following.available()),
	);
	if let Ok(update) = update {
		let path = update.map(|(update, _)| update.prefix.to_string());
		panic!("the announcement stream reported {path:?} with no publisher");
	}
	assert!(resolved.is_err(), "a broadcast resolved with no publisher");

	drop(session);
	drop(relay);
	path.verify();
}

lanes!(no_publisher_never_delivers);

/// The next route and whether it is active.
async fn next_update(announced: &mut moq_net::announce::Consumer) -> Option<(moq_net::announce::Announce, bool)> {
	match announced.next().await? {
		moq_net::announce::Event::Start(route)
		| moq_net::announce::Event::Update(route)
		| moq_net::announce::Event::Restart(route)
		| moq_net::announce::Event::Takeover { announce: route, .. } => Some((route, true)),
		moq_net::announce::Event::End(route) => Some((route, false)),
	}
}

#[tokio::test]
async fn ietf_subscriber_max_age_skips_bufferbloat() {
	subscriber_max_age_skips_bufferbloat("moq-transport-22").await
}

#[tokio::test]
async fn lite_subscriber_max_age_skips_bufferbloat() {
	subscriber_max_age_skips_bufferbloat("moq-lite-06").await
}

/// A finite deep queue, below the media bitrate, must shed superseded groups while
/// preserving the newest catalog snapshot. Random loss is disabled in this acceptance test.
/// On both protocols: this is the benign twin of a subscriber that stalls on purpose, so
/// bounding what a stalled one makes the relay hold must not cost it the live edge.
async fn subscriber_max_age_skips_bufferbloat(version: &str) {
	let version: moq_net::Version = version.parse().unwrap();
	let mut config = relay_config();
	config.listen.version = vec![version];
	let relay = RelayHost::start(config).await;
	let path = Path::through(
		&relay,
		moq_shaper::Profile {
			rate: Some(moq_shaper::Rate {
				bits_per_second: 64_000,
				burst: 1500,
				queue: Duration::from_millis(500),
			}),
			..Default::default()
		},
		19,
	)
	.await;
	let publisher = moq_tokio::origin::spawn();
	let broadcast = publisher.create_broadcast("live").unwrap();
	let mut track = broadcast.create_track(TRACK, timed()).unwrap();
	broadcast.announce(Default::default()).unwrap();
	let mut dial = dial();
	dial.version = vec![version];
	let publish_url = relay.url();
	let publish_session = dial
		.clone()
		.init(quic())
		.unwrap()
		.with_publisher(&publisher)
		.with_reconnect(false)
		.connect(publish_url)
		.established()
		.await
		.unwrap();
	let subscriber = moq_tokio::origin::spawn();
	let consumed = subscriber.consume();
	let subscribe_session = dial
		.init(quic())
		.unwrap()
		.with_subscriber(subscriber)
		.with_reconnect(false)
		.connect(path.url.clone())
		.established()
		.await
		.unwrap();
	write_group(&mut track, b"warmup");
	let remote = tokio::time::timeout(TIMEOUT, consumed.follow("live", None).unwrap().available())
		.await
		.unwrap()
		.unwrap();
	let mut groups = remote
		.track(TRACK)
		.unwrap()
		.subscribe(moq_net::track::Subscription::default().with_max_delay(Duration::from_millis(100)))
		.await
		.unwrap();
	let mut warmup = groups.recv_group().await.unwrap().unwrap();
	assert_eq!(
		warmup.read_frame().await.unwrap().unwrap().payload,
		b"warmup".as_slice()
	);
	tokio::time::timeout(TIMEOUT, async {
		loop {
			if track
				.subscription()
				.is_some_and(|subscription| subscription.max_delay == Some(Duration::from_millis(100)))
			{
				break;
			}
			track.subscription_changed().await.unwrap();
		}
	})
	.await
	.expect("subscriber max age did not reach the publisher");

	// The initial congestion window exceeds this queue's 5.5KB allowance, so this
	// gate proves overflow without depending on how the OS schedules a packet burst.
	let burst = path
		.shaper
		.as_ref()
		.unwrap()
		.burst(moq_shaper::ingress::Direction::Down)
		.unwrap();
	let payload = vec![42u8; 32_000];
	write_group(&mut track, &payload);
	tokio::time::timeout(TIMEOUT, burst.completed())
		.await
		.expect("rate-limit queue never filled")
		.unwrap();
	assert!(path.overflowed() > 0, "the finite queue did not drop overflow");
	// 5.12Mb/s of media behind a 64kb/s link, for a second.
	for sequence in 2..22 {
		let mut group = track.append_group().unwrap();
		group
			.write_frame(moq_net::Timestamp::from_millis(sequence * 50).unwrap(), payload.clone())
			.unwrap();
		group.finish().unwrap();
		tokio::time::sleep(Duration::from_millis(50)).await;
	}
	let mut newest = track.append_group().unwrap();
	newest
		.write_frame(moq_net::Timestamp::from_millis(1100).unwrap(), b"snapshot")
		.unwrap();
	newest.finish().unwrap();
	// No successor means this snapshot must survive even after its budget elapsed.
	tokio::time::sleep(Duration::from_millis(500)).await;
	let sequence = tokio::time::timeout(TIMEOUT, async {
		loop {
			let mut group = groups.recv_group().await.unwrap().expect("subscription ended");
			if let Ok(Some(frame)) = group.read_frame().await
				&& frame.payload == b"snapshot".as_slice()
			{
				break group.sequence;
			}
		}
	})
	.await
	.expect("subscriber did not skip the backlog to the live edge");
	assert_eq!(sequence, 22);
	println!(
		"max age: newest group {sequence}, {} queue-overflow drops",
		path.overflowed()
	);
	drop(groups);
	drop(subscribe_session);
	drop(publish_session);
	path.verify();
}
